const icon = name => '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + icons[name] + '</svg>';

export const appIcon = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 192 192"><rect width="192" height="192" rx="48" fill="#101c2c"/><path d="M139 109a55 55 0 0 1-65-65 55 55 0 1 0 65 65Z" fill="#b7ead8"/><circle cx="133" cy="55" r="7" fill="#b4afff"/></svg>';

export function appManifest(language) {
  return { id: '/app', name: 'MOMO Sleep', short_name: 'MOMO', lang: language === 'en' ? 'en' : 'zh-CN', start_url: '/app?lang=' + language, scope: '/app', display: 'standalone', background_color: '#0b1422', theme_color: '#0b1422', icons: [{ src: '/app/icon.svg', sizes: 'any', type: 'image/svg+xml', purpose: 'any' }] };
}

export function appPage(language = 'zh') {
  const t = (zh, en) => language === 'en' ? en : zh;
  return `<!doctype html><html lang="${language === 'en' ? 'en' : 'zh-CN'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0b1422"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="MOMO"><meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"><meta name="description" content="${t('MOMO 睡眠、积分与权益', 'Your sleep, points and rewards in MOMO')}"><title>${t('MOMO · 我的睡眠', 'MOMO · My sleep')}</title><link rel="icon" href="/app/icon.svg" type="image/svg+xml"><link rel="manifest" href="/app/manifest.webmanifest?lang=${language}"><style>${appStyles}</style></head><body><div class="app-shell"><header class="app-header"><a class="wordmark" href="#today" aria-label="MOMO">${icon('moon')}<span>momo<span class="brand-dot">.</span></span></a><div class="header-actions"><button class="language-button" data-action="language" aria-label="${t('Switch to English', '切换为中文')}" type="button">${t('EN', '中')}</button><span id="connection" class="connection"><i></i>${t('连接中', 'Connecting')}</span><button id="refresh" class="icon-button" type="button" aria-label="${t('刷新账户', 'Refresh account')}">${icon('refresh')}</button></div></header><div id="connection-error" class="error-banner" role="alert" hidden></div><main id="content" aria-busy="true"><div class="loading"><span class="spinner"></span><p>${t('正在读取你的睡眠与积分…', 'Loading your sleep and points…')}</p></div></main><nav class="bottom-nav" aria-label="${t('应用导航', 'App navigation')}">${[['today','moon',t('今日','Today')],['sleep','chart',t('睡眠','Sleep')],['rewards','gift',t('权益','Rewards')],['me','person',t('我的','Me')]].map(([view, image, label]) => `<a href="#${view}" data-tab="${view}">${icon(image)}<span>${label}</span></a>`).join('')}</nav></div><dialog id="sheet" class="sheet"><div id="sheet-content"></div></dialog><div id="toast" class="toast" role="status" aria-live="polite" hidden></div><noscript><p>${t('请启用 JavaScript 以查看睡眠和使用积分。','Enable JavaScript to view sleep and use points.')}</p></noscript><script>${appClientScript}(${JSON.stringify({ language, icons })});</script></body></html>`;
}

