    return '<section class="card sleep-card"><div class="card-top"><h2>' + t('睡眠时长','Time asleep') + '</h2><button class="text-button" data-action="goal">' + t('设置目标','Set goal') + '</button></div><div class="sleep-ring"><svg viewBox="0 0 200 200" role="img" aria-label="' + esc(duration(s.sourceMinutes)) + '"><circle class="ring-track" cx="100" cy="100" r="90"/><circle class="ring-progress" cx="100" cy="100" r="90" stroke-dasharray="' + progress + ' 565.49"/></svg><div class="ring-inner">' + icon('moon') + '<div class="sleep-number">' + Math.floor(s.sourceMinutes / 60) + '<small>' + t('时','h') + '</small>' + s.sourceMinutes % 60 + '<small>' + t('分','m') + '</small></div><div class="goal-label">' + t('目标 ','Goal ') + duration(goalMinutes) + '</div></div></div><div class="sleep-window"><span>' + icon('moon') + '07:36</span><span>—</span><span>' + icon('sun') + '15:13</span></div><div class="sleep-footer"><div><strong>' + s.deepRatioPercent + '<span class="small">%</span></strong><small>' + t('深睡占实际睡眠','Deep / time asleep') + '</small></div><div><strong>' + duration(s.sourceStageMinutes.deep) + '</strong><small>' + t('深度睡眠','Deep sleep') + '</small></div></div></section>';
